// SCRUM-955 staging proof harness (Book Date: an empty count shows the dash, not 0; a count or another figure the chat
// reads two ways holds Book date until a reading is picked or a figure typed), as run on 13 November 2026 (Bangkok) against
// oto-inbox-staging dep-dbr03856e07s738ne6d0 at b70798d3e (the landed lane, the inbox only). Built on the SCRUM-947 harness
// (sign-in, the Simulator, the dialog reader) and the SCRUM-944 booking and archive steps. One file: every script of the run as
// text; `node proof.mjs <folder>` writes them out. The driver keeps ONE headless Chromium open and runs a step per request
// (node go.mjs <step> "<arg>"); credentials by NAME only through scripts/agent/env.mjs need(); staff names held in memory for
// masking only; ZZ TEST names and new ZZ TEST simulator numbers.
// The run, in order: deploys.mjs atStart | inbox-in | app-in 2026-12-12 (the day check) | send A,B,C,D,E,T | wait A,D,E,T|90 |
// send A|@a2 D|@d2 E|@e2 T|@t2 | wait A,D,E,T|60, B,C|30 | open p1|A|01 | act p1.press press-save (02) | act p1.type11 type:Kids 11
// (03) | act p1.del11 back:Kids 2 (04) | act p1.space type:Kids ␠ (05) | act p1.delspace back:Kids 1 | act p1.pick10 pick:kids 10
// (06) | act p1.cancel (07) | open p4|B|08 | act p4.adults0 type:Adults 0 (09) | act p4.cancel | open p5|C|10 | act p5.cancel |
// open p6d|D|11 | act p6d.cancel | open p6e|E|12 | act p6e.pick15 pick:startTime 15:00 (13) | act p6e.age6 type:Turning age 6 (14)
// | act p6e.cancel | open p8b|A|-|book|phone | phonepic 15,16 | act p8b.cancel | open p8c|A|-|beo|phone | phonepic 17,18 | act
// p8c.cancel | open p9t|T|-|book|phone | phonepic 19,20 | hover 21,22 | act p9t.cancel | app-in 2026-12-12 (the day again) | open
// p7|A | act p7.pick12 pick:kids 12 (23) | book A|24 | cleanup (the event archived, every conversation handled, read back) |
// chatpic A|25 | GET /STOP (signs every session out, closes the browser) | deploys.mjs after | receipt.mjs | bundle.cjs.
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
const FILES = {
 "driver.mjs": "// SCRUM-955 staging proof driver (Book Date: an empty count is a dash, a two-way reading is chosen before saving): one headless Chromium kept\n// open, steps run on request (GET http://127.0.0.1:47955/<step>.mjs?arg). Never prints a phone (other than the\n// ZZ TEST simulator number), a password, a token, a setting's value or a person's name.\nimport assert from 'node:assert/strict';\nimport { createServer } from 'node:http';\nimport { createRequire } from 'node:module';\nimport { randomUUID } from 'node:crypto';\nimport { mkdirSync, writeFileSync, existsSync, readFileSync } from 'node:fs';\nimport { pathToFileURL } from 'node:url';\nimport { need } from 'file:///C:/Users/waqar/OneDrive/Desktop/Projects/oto-pos/scripts/agent/env.mjs';\nimport { render, service } from 'file:///C:/Users/waqar/OneDrive/Desktop/Projects/oto-pos/scripts/agent/render.mjs';\n\nconst REPO = 'C:/Users/waqar/OneDrive/Desktop/Projects/oto-pos';\nconst HERE = 'C:/Users/waqar/AppData/Local/Temp/claude/9d4c56906b777e8e/317fcfce-2754-44c9-bec5-9a762ab18d03/scratchpad/p955/h/';\nconst STEPS = HERE + 'steps/';\nconst REL = 'docs/qa/proof-2026-11-13/SCRUM-955';\nconst OUT = REPO + '/' + REL;\nmkdirSync(OUT, { recursive: true });\nconst { chromium, request } = createRequire(REPO + '/apps/pos/package.json')('@playwright/test');\n\nconst SHA = 'b70798d3ef35e024d6bec84380e4370c9f84936a';\nconst CONSOLE = 'https://oto-console-staging.onrender.com';\nconst LAUNCHER = 'https://oto-launcher-staging.onrender.com';\nconst INBOX = 'https://oto-inbox-staging.onrender.com';\nconst APP = 'https://oto-app-staging.onrender.com';\nconst POS = 'https://oto-pos-web-staging.onrender.com';\n\nconst workFile = HERE + 'work.json';\nconst st = existsSync(workFile)\n  ? JSON.parse(readFileSync(workFile, 'utf8'))\n  : { unit: 'SCRUM-955 staging proof', liveCommit: SHA, startedAt: new Date().toISOString(), steps: {}, images: [], convs: {}, log: [] };\nconst save = () => writeFileSync(workFile, JSON.stringify(st, null, 2) + '\\n');\nconst note = (x) => { st.log.push({ at: new Date().toISOString(), ...x }); save(); };\nsave();\n\n// Names to mask, held in memory only (never written, never printed).\nconst NAMES = new Set();\nconst addNames = (...vals) => {\n  for (const v of vals) {\n    if (typeof v !== 'string') continue;\n    const t = v.trim();\n    if (t.length < 2 || /^ZZ TEST/i.test(t)) continue;\n    NAMES.add(t);\n  }\n};\n\nconst browser = await chromium.launch({ headless: true });\nst.browser = 'Chromium ' + browser.version(); save();\nconst pages = {};\nconst newContext = (viewport = { width: 1440, height: 900 }) =>\n  browser.newContext({ viewport, timezoneId: 'Asia/Bangkok', locale: 'en-GB', colorScheme: 'light' });\n\n/** One request through a context's cookie jar; status and body, never throws on status. */\nconst call = async (ctx, origin, method, path, body) => {\n  const headers = method === 'GET' ? {} : { 'Idempotency-Key': randomUUID() };\n  const r = await ctx.request.fetch(origin + '/api' + path, { method, data: body, headers, timeout: 120000 });\n  const text = await r.text();\n  let b = null;\n  try { b = JSON.parse(text); } catch { b = text.slice(0, 300); }\n  return { status: r.status(), body: b };\n};\n\nconst launcherSignIn = async (ctx) => {\n  const s = await call(ctx, LAUNCHER, 'POST', '/auth/sign-in', { phone: need('STAGING_ADMIN_PHONE'), password: need('STAGING_ADMIN_PASSWORD') });\n  assert.equal(s.status, 200, 'launcher sign-in refused: ' + s.status);\n};\nconst handTo = async (ctx, app) => {\n  const h = await call(ctx, LAUNCHER, 'POST', '/auth/handoff', { app });\n  assert.equal(h.status, 200, 'handoff refused: ' + h.status);\n  const page = await ctx.newPage();\n  const want = app === 'oto_app' ? '/api/auth/handoff' : '/api/auth/handoff/exchange';\n  const exchange = page.waitForResponse((r) => new URL(r.url()).pathname === want && r.request().method() === 'POST', { timeout: 90000 });\n  await page.goto(h.body.launchUrl);\n  const response = await exchange;\n  assert.equal(response.status(), 200, app + ' handoff refused');\n  await response.finished();\n  await page.waitForURL((u) => !u.hash.includes('handoff'), { timeout: 60000 });\n  return page;\n};\n\n/** Redact the names: text nodes, input values, placeholders and titles. Returns how many runs were masked. */\nconst redact = async (page) =>\n  page.evaluate((strings) => {\n    const needles = [...new Set(strings)].sort((a, b) => b.length - a.length);\n    if (!needles.length) return 0;\n    const esc = (s) => s.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');\n    const re = new RegExp(needles.map(esc).join('|'), 'gi');\n    let n = 0;\n    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);\n    const hits = [];\n    while (walker.nextNode()) {\n      const t = walker.currentNode;\n      if (t.parentElement?.closest('[data-redacted]')) continue;\n      re.lastIndex = 0;\n      if (re.test(t.nodeValue || '')) hits.push(t);\n    }\n    for (const t of hits) {\n      let html = (t.nodeValue || '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));\n      html = html.replace(re, (m) => { n += 1; return `<span data-redacted=\"1\" style=\"background:#3f3f46;color:#3f3f46;border-radius:3px\">${m.replace(/./g, '█')}</span>`; });\n      const span = document.createElement('span');\n      span.setAttribute('data-redacted', 'wrap');\n      span.innerHTML = html;\n      t.parentNode.replaceChild(span, t);\n    }\n    for (const el of document.querySelectorAll('input, textarea')) {\n      re.lastIndex = 0;\n      if (re.test(el.value || '')) { el.style.color = '#3f3f46'; el.style.background = '#3f3f46'; n += 1; }\n      re.lastIndex = 0;\n      if (el.placeholder && re.test(el.placeholder)) { re.lastIndex = 0; el.placeholder = el.placeholder.replace(re, (m) => '█'.repeat(m.length)); n += 1; }\n    }\n    for (const el of document.querySelectorAll('[title]')) {\n      re.lastIndex = 0;\n      if (re.test(el.getAttribute('title') || '')) { re.lastIndex = 0; el.setAttribute('title', el.getAttribute('title').replace(re, '█')); }\n    }\n    return n;\n  }, [...NAMES]);\n\n/** After a redaction: how many names are still readable in the visible text or in a field. */\nconst leaks = async (page) =>\n  page.evaluate((strings) => {\n    const text = document.body.innerText.toLowerCase();\n    const fields = [...document.querySelectorAll('input, textarea')].map((e) => ((e.style.color === 'rgb(63, 63, 70)' ? '' : e.value) + ' ' + (e.placeholder || '')).toLowerCase()).join(' ');\n    return strings.filter((s) => text.includes(s.toLowerCase()) || fields.includes(s.toLowerCase())).length;\n  }, [...NAMES]);\n\n/** A picture: names redacted, the leak check passed, optional masks and clip / element. */\nconst shot = async (page, name, opts = {}) => {\n  await page.waitForTimeout(opts.settle ?? 700);\n  const masked = await redact(page);\n  const left = await leaks(page);\n  if (left !== 0) throw new Error('a name is still readable; picture not taken: ' + name);\n  const file = OUT + '/' + name;\n  const o = { path: file, mask: opts.mask ?? [], maskColor: '#3f3f46', fullPage: !!opts.fullPage };\n  if (opts.element) await opts.element.screenshot({ path: file, mask: o.mask, maskColor: o.maskColor });\n  else await page.screenshot(o);\n  st.images = st.images.filter((i) => i.file !== name);\n  st.images.push({ file: name, at: new Date().toISOString(), shows: opts.shows ?? null, namesMasked: masked, masks: (opts.mask ?? []).length });\n  save();\n  return name;\n};\n\nconst liveDeploy = async (name) => {\n  const s = await service(name);\n  const d = (await render('GET', `/services/${s.id}/deploys?limit=1`))[0].deploy;\n  return { name, deployId: d.id, status: d.status, sha: d.commit?.id, finishedAt: d.finishedAt };\n};\n\nconst one = (s) => String(s ?? '').replace(/\\s+/g, ' ').trim();\n/** Names out of a string (the signed-in person's), for anything kept. */\nconst scrub = (s) => {\n  if (typeof s !== 'string') return s;\n  let t = s;\n  for (const n of [...NAMES].sort((a, b) => b.length - a.length)) t = t.split(n).join('█');\n  return t.replace(/\\+?\\d[\\d\\s().-]{6,}\\d/g, (m) => ((m.match(/\\d/g) || []).length >= 9 ? '[number]' : m));\n};\n\nconst ctxs = {};\nconst S = { request, POS, need, st, save, note, browser, pages, ctxs, newContext, call, launcherSignIn, handTo, redact, leaks, shot, liveDeploy, addNames, NAMES, SHA, CONSOLE, LAUNCHER, INBOX, APP, OUT, REL, HERE, randomUUID, assert, one, scrub };\n\nconst server = createServer(async (req, res) => {\n  const u = new URL(req.url ?? '/', 'http://x');\n  const file = decodeURIComponent(u.pathname.slice(1));\n  const arg = u.search ? decodeURIComponent(u.search.slice(1)) : '';\n  let out;\n  try {\n    if (file === 'STOP') {\n      const mod = await import(pathToFileURL(STEPS + 'signout.mjs').href + '?t=' + Date.now());\n      out = await mod.default(S, arg).catch((e) => ({ error: String(e?.message ?? e).slice(0, 500) }));\n      save();\n      res.setHeader('content-type', 'application/json');\n      res.end(JSON.stringify(out, null, 2));\n      await browser.close();\n      server.close();\n      process.exit(0);\n    }\n    const mod = await import(pathToFileURL(STEPS + file).href + '?t=' + Date.now());\n    out = { ok: true, result: await mod.default(S, arg) };\n  } catch (e) {\n    out = { ok: false, error: scrub(String(e?.stack ?? e)).slice(0, 3000) };\n  }\n  save();\n  res.setHeader('content-type', 'application/json');\n  res.end(JSON.stringify(out, null, 2));\n});\nserver.listen(47955, '127.0.0.1', () => console.log('driver ready on 47955'));\n",
 "go.mjs": "// Call one driver step with an encoded argument: node go.mjs <step> <arg | @file holding the arg>\nimport { readFileSync } from 'node:fs';\nconst [step, raw = ''] = process.argv.slice(2);\nconst arg = raw.startsWith('@') ? readFileSync(raw.slice(1), 'utf8').trim() : raw;\nconst r = await fetch('http://127.0.0.1:47955/' + step + '.mjs' + (arg ? '?' + encodeURIComponent(arg) : ''), { signal: AbortSignal.timeout(600000) });\nconst j = await r.json();\nif (j.result?.messages) j.result.messages = j.result.messages.length + ' messages';\nconsole.log(JSON.stringify(j, null, 1).slice(0, 8000));\n",
 "deploys.mjs": "// READ-ONLY. The named SCRUM-955 deploy (oto-inbox-staging dep-dbr03856e07s738ne6d0, triggered at b70798d3e) by id,\n// and what the *-staging services the proof touches serve now (the inbox, the api, the OTO App). Never prints the key.\n// node deploys.mjs <out.json> <tag>\nimport { writeFileSync, existsSync, readFileSync } from 'node:fs';\nimport { need } from 'file:///C:/Users/waqar/OneDrive/Desktop/Projects/oto-pos/scripts/agent/env.mjs';\nconst headers = { authorization: `Bearer ${need('RENDER_API_KEY')}`, accept: 'application/json' };\nconst get = async (path) => { const r = await fetch('https://api.render.com/v1' + path, { headers, signal: AbortSignal.timeout(60000) }); return r.ok ? r.json() : { _status: r.status }; };\nconst want = { 'oto-inbox-staging': 'dep-dbr03856e07s738ne6d0', 'oto-api-staging': null, 'oto-app-staging': null };\nconst services = (await get('/services?limit=50')).map((r) => r.service ?? r).filter((s) => /-staging$/.test(s.name));\nconst out = process.argv[2];\nconst tag = process.argv[3] ?? 'read';\nconst state = existsSync(out) ? JSON.parse(readFileSync(out, 'utf8')) : {\n  note: 'SCRUM-955 landed on main at b70798d3ef35e024d6bec84380e4370c9f84936a (the inbox only: no platform change, no migration). oto-inbox-staging was deployed at that commit at 01:12 Bangkok on 13 November (dep-dbr03856e07s738ne6d0). Read-only reads of the Render API; no service was changed by this proof. The api and the OTO App are recorded as they were (the proof uses the api through the inbox and the OTO App for the day check and the archive).',\n};\nconst snap = { readAt: new Date().toISOString(), services: {} };\nfor (const [name, dep] of Object.entries(want)) {\n  const s = services.find((x) => x.name === name);\n  if (!s) { snap.services[name] = null; continue; }\n  const d = dep ? await get(`/services/${s.id}/deploys/${dep}`) : null;\n  const list = (await get(`/services/${s.id}/deploys?limit=5`)).map((x) => x.deploy ?? x);\n  const live = list.find((x) => x.status === 'live');\n  snap.services[name] = {\n    ...(d ? { named: { id: d.id, status: d.status, sha: d.commit?.id, createdAt: d.createdAt, finishedAt: d.finishedAt, trigger: d.trigger ?? null } } : {}),\n    live: live ? { id: live.id, sha: live.commit?.id, createdAt: live.createdAt, finishedAt: live.finishedAt } : null,\n    latest: list[0] ? { id: list[0].id, status: list[0].status, sha: list[0].commit?.id, createdAt: list[0].createdAt } : null,\n  };\n}\nsnap.inboxLiveOnTheNamedDeploy = snap.services['oto-inbox-staging']?.live?.id === want['oto-inbox-staging'];\nsnap.inboxLiveSha = snap.services['oto-inbox-staging']?.live?.sha ?? null;\nstate[tag] = snap;\nwriteFileSync(out, JSON.stringify(state, null, 2) + '\\n');\nconsole.log(JSON.stringify(snap, null, 1));\n",
 "receipt.mjs": "// Builds docs/qa/proof-2026-11-13/SCRUM-955/receipt.json from the driver's work file: each ZZ TEST thread's lines as\n// sent, every Book Date window read (each count box's value and placeholder, the readings offered, the footer's waiting\n// line, the save button's disabled state and title), every action and its read, the press on the held button with the\n// requests it made, the booking and its read-back, the phone-width measures, the clean-up and the sign-out, each point's\n// verdict. Scrubbed: no staff name, no phone (the 668999551xx ZZ TEST simulator numbers are not written here).\nimport { readFileSync, writeFileSync, readdirSync } from 'node:fs';\nconst HERE = 'C:/Users/waqar/AppData/Local/Temp/claude/9d4c56906b777e8e/317fcfce-2754-44c9-bec5-9a762ab18d03/scratchpad/p955/h/';\nconst DIR = 'C:/Users/waqar/OneDrive/Desktop/Projects/oto-pos/docs/qa/proof-2026-11-13/SCRUM-955/';\nconst st = JSON.parse(readFileSync(HERE + 'work.json', 'utf8'));\nconst pick = (o, keys) => Object.fromEntries(keys.filter((k) => o && k in o).map((k) => [k, o[k]]));\nconst act = (tag) => st.acts.find((a) => a.tag === tag);\nconst win = (d) => d && ({\n  kids: d.boxes.kids, adults: d.boxes.adults, turningAge: d.boxes.childAge,\n  readings: Object.fromEntries(Object.entries(d.fields).filter(([, f]) => f.choice).map(([k, f]) => [k, f.choice])),\n  lineUnder: Object.fromEntries(['date', 'startTime', 'kids', 'adults', 'childAge'].map((k) => [k, d.fields[k].hint])),\n  values: Object.fromEntries(['date', 'startTime', 'park', 'bookingName'].map((k) => [k, d.fields[k].value])),\n  footerWaitingLine: d.waitingLine, saveButton: d.saveButton, refusalLine: d.refusal, header: d.header.readLine,\n});\nconst opened = (tag) => { const p = st.points[tag]; return p && { conversation: p.key, pressed: p.pressed, viewport: p.viewport, buttonsBefore: p.buttonsBefore, readWaitedMs: p.readWaitedMs, proposalRoute: p.proposalRoute, window: win(p.dialog), picture: p.picture ?? null }; };\nconst did = (tag) => { const a = act(tag); return a && { action: a.action, value: a.value, boxAfter: a.boxAfter ?? undefined, readingsBefore: a.chipsBefore ?? undefined, window: win(a.dialog), afterCancel: a.afterCancel, picture: a.picture ?? null }; };\nconst press = act('p1.press');\nconst receipt = {\n  unit: 'SCRUM-955 staging proof',\n  ticket: 'SCRUM-955',\n  title: 'Book Date: an empty count does not read as 0, and a count the chat reads two ways is chosen before saving',\n  landedCommit: 'b70798d3ef35e024d6bec84380e4370c9f84936a',\n  deploys: 'see deploys.json (oto-inbox-staging dep-dbr03856e07s738ne6d0, live at b70798d3e before and after the run)',\n  startedAt: st.startedAt,\n  finishedAt: st.signOut?.at ?? null,\n  browser: st.browser + ' (one headless browser, closed at the end)',\n  rules: 'ZZ TEST conversations on the inbox simulator only, each from a new ZZ TEST simulator number, invented names; one ZZ TEST event booked (point 7) on a day with no real party (checked first) and archived after, read back; every conversation marked handled, read back; no direct database write; staff names and the phone box masked in pictures and kept out of this file; every session signed out',\n  inboxViewer: st.inboxViewer && pick(st.inboxViewer, ['roles', 'birthdaysTeams']),\n  conversations: Object.fromEntries(Object.entries(st.convs).map(([k, c]) => [k, {\n    id: c.id, name: c.name, language: c.language, from: 'a new ZZ TEST simulator number of this run',\n    lines: (c.lines ?? []).map((l) => pick(l, ['n', 'by', 'text', 'at', 'path', 'status', 'outcome', 'conversationsCreated', 'reopened', 'dialogSaid'])),\n    assistant: c.turns ? Object.values(c.turns).map((t) => ({ afterLine: t.afterLine, turnShown: t.turnShown, kinds: (t.turns ?? []).map((x) => x.kind), aiState: t.aiState })) : null,\n  }])),\n  points: {\n    '1 two ways (kids)': {\n      verdict: 'PASS',\n      opened: opened('p1'),\n      pressOnTheHeldBookDate: press && { how: 'a real mouse press on the button\\'s centre', before: press.before, requestsIn5s: press.requestsIn5s, writesIn5s: press.writesIn5s, windowStillOpen: press.windowStillOpen, window: win(press.dialog), picture: press.picture },\n    },\n    '2 a typed figure frees it': {\n      verdict: 'PASS',\n      typed11: did('p1.type11'), deleted11: did('p1.del11'), aSpaceTypedFirst: did('p1.space'), spaceDeleted: did('p1.delspace'),\n    },\n    '3 a pick frees it': { verdict: 'PASS', picked10: did('p1.pick10'), cancel: did('p1.cancel') },\n    '4 no count at all': { verdict: 'PASS', opened: opened('p4'), typed0InAdults: did('p4.adults0'), cancel: did('p4.cancel') },\n    '5 a stated zero': { verdict: 'PASS', opened: opened('p5'), cancel: did('p5.cancel') },\n    '6 another field two ways': {\n      verdict: 'PASS for the start time and the age; the adults (the lane\\'s step 10 exactly) cannot be read two ways: the pattern never reads adults (apps/inbox/src/lib/beo.ts:195 numAdults is always empty), so the model\\'s 6 fills the box with no choice, as the lane said',\n      adultsLaneStep10: { opened: opened('p6d'), cancel: did('p6d.cancel') },\n      startTimeAndAge: { opened: opened('p6e'), pickedStartTime1500: did('p6e.pick15'), typed6InTheAge: did('p6e.age6'), cancel: did('p6e.cancel') },\n    },\n    '7 a whole booking': {\n      verdict: 'PASS',\n      dayChecks: st.dayChecks,\n      opened: opened('p7'), picked12: did('p7.pick12'),\n      booked: st.booked && pick(st.booked, ['at', 'bookingName', 'save', 'note', 'chip', 'buttons', 'afterPicture', 'convEvent']),\n      eventRemoved: st.cleanup?.events, upcomingListAfter: st.cleanup?.upcomingLiveList,\n      conversationAfter: st.after?.A,\n    },\n    '8 phone width 375 by 812': {\n      verdict: 'PASS from the conversation\\'s Book Date (the line squeezed to three lines, whole); DEFECT from Create BEO (the line crushed to 0 px wide, its words one per line under the Cancel button, the footer 223 px tall)',\n      fromBookDate: { opened: opened('p8b'), measure: st.phone?.[0]?.measure, pictures: [st.phone?.[0]?.picture, st.phone?.[0]?.footerPicture], cancel: did('p8b.cancel') },\n      fromCreateBeo: { opened: opened('p8c'), measure: st.phone?.[1]?.measure, pictures: [st.phone?.[1]?.picture, st.phone?.[1]?.footerPicture], cancel: did('p8c.cancel') },\n    },\n  },\n  hunt: {\n    thaiTwoWaysAtPhoneWidth: { opened: opened('p9t'), measure: st.phone?.[2]?.measure, pictures: [st.phone?.[2]?.picture, st.phone?.[2]?.footerPicture], cancel: did('p9t.cancel') },\n    heldButtonUnderTheMouse: JSON.parse(JSON.stringify(st.hover ?? null).replace(/oklch\\(([^)]*)\\)/g, (m, v) => 'oklch(' + v.trim().split(/\\s+/).join(', ') + ')')),\n  },\n  cleanup: st.cleanup,\n  signOut: st.signOut,\n  images: st.images,\n  imagesInTheFolder: readdirSync(DIR).filter((f) => f.endsWith('.png')).sort(),\n};\nlet text = JSON.stringify(receipt, null, 2);\n// Ids (uuids, deploy ids) and the browser's version are kept whole; any other long run of digits is masked.\nconst kept = [];\ntext = text.replace(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}|Chromium [\\d.]+/gi, (m) => { kept.push(m); return `\\u0000${kept.length - 1}\\u0000`; });\ntext = text.replace(/\\+?\\d[\\d\\s().-]{7,}\\d/g, (m) => ((m.match(/\\d/g) || []).length >= 9 ? '[number]' : m));\ntext = text.replace(/\\u0000(\\d+)\\u0000/g, (_, i) => kept[Number(i)]);\nwriteFileSync(DIR + 'receipt.json', text + '\\n');\nconsole.log('written', text.length);\n",
 "steps/act.mjs": "// One thing done in the open Book Date window as a person does it, then the window read again (and pictured).\n// arg = \"<tag>|<action>|<value>|<picture file or ->\". Actions:\n//   type:<aria>   keys typed one by one at the end of that box (value = the keys; \"␠\" stands for a space)\n//   back:<aria>   Backspace pressed <value> times at the end of that box\n//   pick:<field>  the reading whose figure is <value> pressed under that field\n//   press-save    a real mouse press on the save button's centre (disabled or not), every request the page makes in\n//                 the next 5 s recorded (method and path), and whether the window is still open\n//   cancel        Cancel pressed; the conversation read back (its event) and its buttons read\n//   read          nothing done; the window read\nimport { dialogOf, readDialog, dialogShot, brief } from './bd.mjs';\nimport { prepInbox, maskInitials } from './look.mjs';\nimport { maskNumbers } from './thread.mjs';\nconst esc = (s) => s.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');\nexport default async (S, arg) => {\n  const [tag, action, rawValue = '', pic = '-'] = arg.split('|');\n  const value = rawValue.replace(/␠/g, ' ');\n  const { page, ctx } = S.ctxs.inbox;\n  const dialog = dialogOf(page);\n  const rec = { tag, at: new Date().toISOString(), action, value: rawValue };\n  const [kind, target] = action.split(':');\n  if (kind === 'type' || kind === 'back') {\n    const box = dialog.locator(`input[aria-label=\"${target}\"]`).first();\n    await box.click();\n    await page.keyboard.press('End');\n    if (kind === 'type') await page.keyboard.type(value, { delay: 80 });\n    else for (let i = 0; i < Number(value); i++) await page.keyboard.press('Backspace');\n    await page.waitForTimeout(500);\n    rec.boxAfter = await box.inputValue();\n  } else if (kind === 'pick') {\n    const chips = dialog.locator(`[data-choice=\"${target}\"] button`);\n    rec.chipsBefore = (await chips.allInnerTexts()).map((t) => S.scrub(S.one(t)));\n    const chip = chips.filter({ has: page.locator('span.font-medium', { hasText: new RegExp('^' + esc(value) + '$') }) }).first();\n    await chip.click();\n    await page.waitForTimeout(500);\n  } else if (action === 'press-save') {\n    const save = dialog.getByRole('button', { name: /^Book date/ }).first();\n    rec.before = { disabled: await save.isDisabled(), title: await save.getAttribute('title') };\n    const requests = [];\n    const onReq = (r) => { const u = new URL(r.url()); requests.push({ method: r.method(), host: u.host, path: u.pathname, at: new Date().toISOString() }); };\n    page.on('request', onReq);\n    const box = await save.boundingBox();\n    await page.mouse.click(box.x + box.width / 2, box.y + box.height / 2);\n    await page.waitForTimeout(5000);\n    page.off('request', onReq);\n    rec.pressedAt = { x: Math.round(box.x + box.width / 2), y: Math.round(box.y + box.height / 2) };\n    rec.requestsIn5s = requests;\n    rec.writesIn5s = requests.filter((r) => r.method !== 'GET' || /book-date$/.test(r.path));\n    rec.windowStillOpen = await dialog.isVisible();\n  } else if (action === 'cancel') {\n    await dialog.getByRole('button', { name: 'Cancel', exact: true }).click();\n    await dialog.waitFor({ state: 'hidden', timeout: 15000 });\n    await page.waitForTimeout(800);\n    const key = Object.keys(S.st.convs).find((k) => S.st.convs[k].id === S.st.points?.[tag.split('.')[0]]?.conversationId) ?? null;\n    const id = key ? S.st.convs[key].id : null;\n    const d = id ? await S.call(ctx, S.INBOX, 'GET', '/inbox/conversations/' + id) : null;\n    const chat = page.locator('section[aria-label=\"Conversation\"]');\n    rec.afterCancel = {\n      key, route: 'GET /api/inbox/conversations/:id', status: d?.status ?? null, event: d?.body?.event ?? null,\n      buttons: (await chat.getByRole('button', { name: /^(Book Date|Date Booked|Event archived|Create BEO)$/ }).allInnerTexts()).map((t) => t.trim()),\n    };\n    if (pic !== '-') {\n      const vp = page.viewportSize();\n      if (vp && vp.width > 1000) {\n        await prepInbox(S, page);\n        await page.setViewportSize({ width: 1440, height: 900 });\n      }\n      await maskInitials(S, page);\n      await maskNumbers(page);\n      const list = page.locator('section[aria-label=\"Conversations\"]');\n      rec.picture = await S.shot(page, pic, { element: chat, mask: [list], shows: 'After Cancel: the conversation, its button still Book Date (no event)' });\n    }\n    (S.st.acts ??= []).push(rec);\n    S.save();\n    return rec;\n  } else if (action !== 'read') {\n    throw new Error('no action ' + action);\n  }\n  rec.dialog = await readDialog(S, page);\n  if (pic !== '-') {\n    const vp = page.viewportSize();\n    if (vp && vp.width < 500) {\n      await maskInitials(S, page);\n      await maskNumbers(page);\n      rec.picture = await S.shot(page, pic, { mask: [dialog.locator('input[aria-label=\"Phone\"]')], settle: 400, shows: `${action} ${rawValue} at phone width` });\n    } else {\n      rec.picture = await dialogShot(S, page, pic, `${action} ${rawValue}: the window after it`);\n    }\n  }\n  (S.st.acts ??= []).push(rec);\n  S.save();\n  const { dialog: d, ...rest } = rec;\n  return { ...rest, ...brief(d) };\n};\n",
 "steps/app-in.mjs": "// The staging administrator in the OTO App through the launcher (a second session, for the day check before the\n// booking and for the archive after it); the signed-in person's names held for masking; Central Floresta found by\n// name; the park's events on the day read (only whether each is a ZZ TEST one, its id, status and time: no title of a\n// real party is kept). arg = \"<YYYY-MM-DD>\".\nexport default async (S, arg) => {\n  const day = arg || '2026-12-12';\n  if (!S.ctxs.app) {\n    const ctx = await S.newContext({ width: 1280, height: 900 });\n    ctx.setDefaultTimeout(30000);\n    await S.launcherSignIn(ctx);\n    const page = await S.handTo(ctx, 'oto_app');\n    S.ctxs.app = { ctx, page };\n  }\n  const { ctx } = S.ctxs.app;\n  const u = await S.call(ctx, S.APP, 'GET', '/user');\n  S.assert.equal(u.status, 200, '/api/user ' + u.status);\n  for (const v of [u.body?.fullName, u.body?.firstName, u.body?.lastName, u.body?.nickname, u.body?.displayName, u.body?.username, u.body?.name]) {\n    S.addNames(v);\n    if (typeof v === 'string') for (const part of v.trim().split(/\\s+/)) if (part.length >= 3) S.addNames(part);\n  }\n  const br = await S.call(ctx, S.APP, 'GET', '/branches');\n  const cf = (Array.isArray(br.body) ? br.body : []).find((b) => /Central Floresta/.test(b.name));\n  S.assert.ok(cf, 'Central Floresta not found');\n  const ev = await S.call(ctx, S.APP, 'GET', `/admin/events?range=all&includeArchived=true&branchId=${cf.id}`);\n  const all = Array.isArray(ev.body) ? ev.body : [];\n  const dayOf = (e) => String(e.eventDate ?? e.date ?? '').slice(0, 10);\n  const onDay = all.filter((e) => dayOf(e) === day).map((e) => ({\n    id: e.id, zzTest: /ZZ TEST|ZZ Test/i.test(String(e.title || '')), archived: !!(e.archivedAt || e.isArchived),\n    startTime: e.startTime ?? e.eventTime ?? null, status: e.statusName ?? e.status ?? null,\n  }));\n  const rec = {\n    at: new Date().toISOString(), role: u.body?.role ?? null, centralFloresta: cf.id,\n    listRoute: { route: 'GET /api/admin/events?range=all&includeArchived=true&branchId=<Central Floresta>', status: ev.status, events: all.length },\n    day, onDay,\n    realLivePartiesOnDay: onDay.filter((e) => !e.zzTest && !e.archived).length,\n  };\n  S.st.app = { ...(S.st.app ?? {}), centralFloresta: cf.id };\n  (S.st.dayChecks ??= []).push(rec);\n  S.save();\n  return rec;\n};\n",
 "steps/bd.mjs": "// Book Date dialog helpers (the thread page of the inbox session).\nimport { prepInbox, maskInitials } from './look.mjs';\nimport { maskNumbers } from './thread.mjs';\nexport const FIELDS = { date: 'Date', startTime: 'Start time', park: 'Park', kids: 'Kids', adults: 'Adults', bookingName: 'Booking name', phone: 'Phone', childName: \"Child's name\", childAge: 'Turning age' };\nexport const openThread = async (S, key) => {\n  const conv = S.st.convs[key];\n  if (!conv?.id) throw new Error('no conversation for ' + key);\n  const { page } = S.ctxs.inbox;\n  await page.setViewportSize({ width: 1440, height: 1500 });\n  await page.goto(S.INBOX + '/?c=' + conv.id);\n  const section = page.locator('section[aria-label=\"Conversation\"]');\n  await section.waitFor({ timeout: 60000 });\n  await section.getByRole('button', { name: /^(Book Date|Date Booked|Event archived)$/ }).first().waitFor({ timeout: 60000 });\n  await prepInbox(S, page);\n  await page.waitForTimeout(1200);\n  return page;\n};\nexport const dialogOf = (page) => page.getByRole('dialog').filter({ has: page.locator('input[aria-label=\"Date\"]') });\n/** The dialog as it stands: every field's value and the line under it, the header's lines, the fetch line. */\nexport const readDialog = async (S, page) => {\n  const dialog = dialogOf(page);\n  const out = { title: S.scrub(S.one(await dialog.locator('h3').first().innerText().catch(() => ''))), fields: {} };\n  for (const [k, aria] of Object.entries(FIELDS)) {\n    const label = dialog.locator('label', { has: page.locator(`[aria-label=\"${aria}\"]`) }).first();\n    const control = dialog.locator(`[aria-label=\"${aria}\"]`).first();\n    const value = k === 'park' ? await control.evaluate((el) => el.selectedOptions[0]?.textContent ?? '') : await control.inputValue();\n    const text = S.one(await label.innerText());\n    const hint = text.replace(new RegExp('^' + aria.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&') + '\\\\s*'), '').replace(/^# of (kids|adults)\\s*/, '').trim();\n    const choice = label.locator('[data-choice]');\n    out.fields[k] = {\n      value: k === 'phone' ? (value ? '[number]' : '') : k === 'bookingName' ? (/^ZZ TEST/.test(value) ? value : S.scrub(value)) : value,\n      hint: k === 'phone' || k === 'bookingName' ? null : S.scrub(hint) || null,\n      ...((await choice.count()) ? { choice: (await choice.locator('button').allInnerTexts()).map((t) => S.scrub(S.one(t))) } : {}),\n    };\n  }\n  out.header = {\n    reading: await dialog.getByTestId('book-date-reading').isVisible().catch(() => false),\n    read: await dialog.getByTestId('book-date-read').isVisible().catch(() => false),\n    readLine: S.one(await dialog.getByTestId('book-date-read').innerText().catch(() => '')) || null,\n    fetchButton: S.one(await dialog.getByTestId('button-fetch-from-chat').innerText().catch(() => '')) || null,\n    fetchButtonEnabled: await dialog.getByTestId('button-fetch-from-chat').isEnabled().catch(() => null),\n    fetchButtonTitle: await dialog.getByTestId('button-fetch-from-chat').getAttribute('title').catch(() => null),\n    fetchedLine: S.one(await dialog.getByTestId('book-date-fetched').innerText().catch(() => '')) || null,\n  };\n  out.footer = (await dialog.locator('button').allInnerTexts()).map((t) => S.one(t)).filter((t) => /^(Cancel|Book date)/.test(t));\n  out.refusal = S.scrub(S.one(await dialog.locator('[role=alert]').innerText().catch(() => ''))) || null;\n  // SCRUM-955: each count box's value and placeholder (an empty box shows the placeholder), the footer's waiting line,\n  // and the save button's state and title.\n  out.boxes = {};\n  for (const [k, aria] of [['kids', 'Kids'], ['adults', 'Adults'], ['childAge', 'Turning age']]) {\n    const c = dialog.locator(`input[aria-label=\"${aria}\"]`).first();\n    const value = await c.inputValue();\n    const placeholder = await c.getAttribute('placeholder');\n    out.boxes[k] = { value, placeholder, shows: value !== '' ? value + ' (a value)' : (placeholder ?? '') + ' (the placeholder)' };\n  }\n  const waiting = dialog.getByTestId('book-date-waiting');\n  out.waitingLine = (await waiting.count()) ? S.one(await waiting.innerText()) : null;\n  const save = dialog.getByRole('button', { name: /^Book date/ }).first();\n  out.saveButton = {\n    text: S.one(await save.innerText()),\n    disabled: await save.isDisabled(),\n    title: await save.getAttribute('title'),\n    opacity: await save.evaluate((el) => getComputedStyle(el).opacity),\n  };\n  return out;\n};\n/** The short form of a dialog read: what each point checks. */\nexport const brief = (d) => ({\n  kids: d.boxes.kids, adults: d.boxes.adults, childAge: d.boxes.childAge,\n  kidsChoice: d.fields.kids.choice ?? null, adultsChoice: d.fields.adults.choice ?? null,\n  startTime: { value: d.fields.startTime.value, hint: d.fields.startTime.hint, choice: d.fields.startTime.choice ?? null },\n  date: { value: d.fields.date.value, hint: d.fields.date.hint, choice: d.fields.date.choice ?? null },\n  ageHint: d.fields.childAge.hint, ageChoice: d.fields.childAge.choice ?? null,\n  waitingLine: d.waitingLine, saveButton: d.saveButton, refusal: d.refusal, footer: d.footer, read: d.header.readLine,\n});\n/** A picture of the dialog: names and initials masked, the phone field covered, any long digit run masked. */\nexport const dialogShot = async (S, page, file, shows) => {\n  await maskInitials(S, page);\n  await maskNumbers(page);\n  const dialog = dialogOf(page);\n  const phone = dialog.locator('input[aria-label=\"Phone\"]');\n  return S.shot(page, file, { element: dialog, mask: [phone], settle: 400, shows });\n};\n",
 "steps/book.mjs": "// Point 7: in the open Book Date window (a reading already chosen), the window's own \"Book date\" pressed: the api's\n// answer, the note and the event chip; the conversation's event read back. arg = \"<key>|<afterPic or ->|<date or ->\".\nimport { dialogOf, readDialog, brief } from './bd.mjs';\nimport { prepInbox, maskInitials } from './look.mjs';\nimport { maskNumbers } from './thread.mjs';\nexport default async (S, arg) => {\n  const [key, afterPic = '-', date = '-'] = arg.split('|');\n  const conv = S.st.convs[key];\n  if (!/^ZZ TEST/.test(conv.name)) throw new Error('refusing a conversation not named ZZ TEST');\n  const { page, ctx } = S.ctxs.inbox;\n  const dialog = dialogOf(page);\n  const chat = page.locator('section[aria-label=\"Conversation\"]');\n  const rec = { at: new Date().toISOString(), key };\n  if (date !== '-') {\n    await dialog.locator('input[aria-label=\"Date\"]').fill(date);\n    rec.dateTyped = date;\n  }\n  const at = await readDialog(S, page);\n  rec.valuesAtSave = brief(at);\n  rec.bookingName = at.fields.bookingName.value;\n  if (!/^ZZ TEST/.test(rec.bookingName)) throw new Error('the booking name is not ZZ TEST: not booking');\n  const [resp] = await Promise.all([\n    page.waitForResponse((r) => /\\/api\\/inbox\\/conversations\\/[^/]+\\/book-date$/.test(new URL(r.url()).pathname) && r.request().method() === 'POST', { timeout: 120000 }),\n    dialog.getByRole('button', { name: 'Book date', exact: true }).click(),\n  ]);\n  let body = null;\n  try { body = await resp.json(); } catch {}\n  let sent = null;\n  try { const j = resp.request().postDataJSON(); sent = { date: j.date, startTime: j.startTime, kids: j.kids, adults: j.adults, childName: j.childName, childAge: j.childAge, branchId: j.branchId, contactName: j.contactName, hasId: !!j.id }; } catch {}\n  rec.save = {\n    route: \"POST /api/inbox/conversations/:id/book-date (the window's Book date)\", status: resp.status(), sent,\n    error: [200, 201].includes(resp.status()) ? null : body?.error ?? body,\n    event: body?.event ? { id: body.event.id, title: body.event.title ?? null, date: body.event.date ?? null, startTime: body.event.startTime ?? null, statusName: body.event.statusName ?? null, branchName: body.event.branchName ?? null, kids: body.event.kids ?? null, adults: body.event.adults ?? null } : null,\n  };\n  S.save();\n  if (![200, 201].includes(resp.status())) {\n    await page.waitForTimeout(1500);\n    rec.dialogRefusal = S.scrub(S.one(await dialog.innerText().catch(() => ''))).slice(-400);\n    S.st.booked = rec;\n    S.save();\n    return rec;\n  }\n  (S.st.events ??= {})[key] = { id: body.event.id, title: body.event.title ?? null, date: body.event.date ?? null, startTime: body.event.startTime ?? null, bookedAt: new Date().toISOString() };\n  S.save();\n  await dialog.waitFor({ state: 'hidden', timeout: 30000 });\n  const noteEl = chat.getByText(/tentative in the Events calendar/).first();\n  await noteEl.waitFor({ timeout: 30000 }).catch(() => null);\n  await page.getByTestId('event-chip').first().waitFor({ timeout: 30000 }).catch(() => null);\n  await page.waitForTimeout(1200);\n  rec.note = S.one(await noteEl.innerText().catch(() => '')) || null;\n  rec.chip = S.one(await page.getByTestId('event-chip').first().innerText().catch(() => '')) || null;\n  rec.buttons = (await chat.getByRole('button', { name: /^(Book Date|Date Booked|Event archived|Create BEO)$/ }).allInnerTexts()).map((t) => t.trim());\n  if (afterPic !== '-') {\n    await prepInbox(S, page);\n    await page.setViewportSize({ width: 1440, height: 900 });\n    await maskInitials(S, page);\n    await maskNumbers(page);\n    const list = page.locator('section[aria-label=\"Conversations\"]');\n    rec.afterPicture = await S.shot(page, afterPic, { element: chat, mask: [list], shows: 'After Book date: the note \"tentative in the Events calendar\", the button Date Booked and the event chip' });\n  }\n  const d = await S.call(ctx, S.INBOX, 'GET', '/inbox/conversations/' + conv.id);\n  rec.convEvent = d.body?.event ? { id: d.body.event.id, title: d.body.event.title, date: d.body.event.date, startTime: d.body.event.startTime, branchId: d.body.event.branchId, status: d.body.event.status ?? d.body.event.statusName, kids: d.body.event.kids, adults: d.body.event.adults, archived: d.body.event.archived ?? null } : null;\n  S.st.booked = rec;\n  S.save();\n  return rec;\n};\n",
 "steps/chatpic.mjs": "// A ZZ TEST conversation as it reads now (after the clean-up): its buttons read and the conversation pictured with the\n// list beside it masked. arg = \"<key>|<picture>\".\nimport { prepInbox, maskInitials } from './look.mjs';\nimport { maskNumbers } from './thread.mjs';\nexport default async (S, arg) => {\n  const [key, pic] = arg.split('|');\n  const conv = S.st.convs[key];\n  if (!/^ZZ TEST/.test(conv.name)) throw new Error('refusing a conversation not named ZZ TEST');\n  const { page } = S.ctxs.inbox;\n  await page.setViewportSize({ width: 1440, height: 900 });\n  await page.goto(S.INBOX + '/?c=' + conv.id);\n  const chat = page.locator('section[aria-label=\"Conversation\"]');\n  await chat.waitFor({ timeout: 60000 });\n  await chat.getByRole('button', { name: /^(Book Date|Date Booked|Event archived)$/ }).first().waitFor({ timeout: 60000 });\n  await prepInbox(S, page);\n  await page.setViewportSize({ width: 1440, height: 900 });\n  await page.waitForTimeout(1200);\n  const rec = { at: new Date().toISOString(), key };\n  rec.buttons = (await chat.getByRole('button', { name: /^(Book Date|Date Booked|Event archived|Create BEO|Mark as Handled|Reopen)$/ }).allInnerTexts()).map((t) => t.trim());\n  rec.archivedTitle = await chat.getByRole('button', { name: 'Event archived', exact: true }).getAttribute('title').catch(() => null);\n  await maskInitials(S, page);\n  await maskNumbers(page);\n  rec.picture = await S.shot(page, pic, { element: chat, mask: [page.locator('section[aria-label=\"Conversations\"]')], shows: 'After the clean-up: the event archived, the conversation handled' });\n  (S.st.after ??= {})[key] = rec;\n  S.save();\n  return rec;\n};\n",
 "steps/cleanup.mjs": "// Clean-up, each read back: the ZZ TEST event of point 7 archived through the OTO App's own archive route\n// (POST /api/admin/events/:id/archive {archived:true}, as the SCRUM-944 proof did) and read back, the park's live\n// upcoming events checked for any ZZ TEST one of this run; every ZZ TEST conversation of this run marked handled through\n// the inbox's own route (POST /api/inbox/conversations/:id/handle, as the SCRUM-947 proof did) and read back.\nexport default async (S) => {\n  const out = { at: new Date().toISOString(), events: {}, conversations: {} };\n  if (S.st.events && Object.keys(S.st.events).length) {\n    const { ctx } = S.ctxs.app;\n    for (const [key, ev] of Object.entries(S.st.events)) {\n      const title = ev.title ?? '';\n      if (!/ZZ TEST/i.test(title)) throw new Error('refusing to archive an event not named ZZ TEST: ' + key);\n      const a = await S.call(ctx, S.APP, 'POST', `/admin/events/${ev.id}/archive`, { archived: true });\n      const after = await S.call(ctx, S.APP, 'GET', `/admin/events/${ev.id}`);\n      out.events[key] = {\n        id: ev.id, title,\n        archive: { route: 'POST /api/admin/events/:id/archive', status: a.status, archivedAt: a.body?.archivedAt ?? null, isArchived: a.body?.isArchived ?? null, error: a.status < 300 ? null : a.body?.message ?? a.body },\n        readBack: { route: 'GET /api/admin/events/:id', status: after.status, archivedAt: after.body?.archivedAt ?? null, isArchived: after.body?.isArchived ?? null },\n      };\n    }\n    const ids = new Set(Object.values(S.st.events).map((e) => e.id));\n    const list = await S.call(ctx, S.APP, 'GET', `/admin/events?range=upcoming&branchId=${S.st.app.centralFloresta}`);\n    out.upcomingLiveList = {\n      route: 'GET /api/admin/events?range=upcoming&branchId=<Central Floresta>', status: list.status,\n      thisRunsEventsStillListed: Array.isArray(list.body) ? list.body.filter((e) => ids.has(e.id)).map((e) => ({ id: e.id, title: e.title, archived: !!(e.archivedAt || e.isArchived) })) : null,\n      zzTest955Listed: Array.isArray(list.body) ? list.body.filter((e) => /ZZ TEST 955/i.test(String(e.title || ''))).map((e) => ({ id: e.id, title: e.title, archived: !!(e.archivedAt || e.isArchived) })) : null,\n    };\n  }\n  const ic = S.ctxs.inbox.ctx;\n  for (const [key, conv] of Object.entries(S.st.convs)) {\n    if (!/^ZZ TEST/.test(conv.name)) throw new Error('refusing a conversation not named ZZ TEST: ' + key);\n    const h = await S.call(ic, S.INBOX, 'POST', '/inbox/conversations/' + conv.id + '/handle');\n    const d = await S.call(ic, S.INBOX, 'GET', '/inbox/conversations/' + conv.id);\n    const c = d.body?.conversation ?? d.body;\n    out.conversations[key] = {\n      id: conv.id, name: conv.name,\n      handle: { route: 'POST /api/inbox/conversations/:id/handle', status: h.status, error: h.status === 200 ? null : h.body?.error ?? null },\n      readBack: { route: 'GET /api/inbox/conversations/:id', status: d.status, state: c?.status ?? c?.state ?? null, handledAt: c?.handledAt ?? null, event: d.body?.event ? { id: d.body.event.id, archived: d.body.event.archived ?? null, statusName: d.body.event.statusName ?? null } : null },\n    };\n  }\n  S.st.cleanup = out;\n  S.save();\n  return out;\n};\n",
 "steps/hover.mjs": "// The hunt: the held save button with the mouse away and with the mouse over it (its background, opacity and cursor),\n// pictured both ways (the footer alone). arg = \"<picture away>|<picture over>\".\nimport { dialogOf } from './bd.mjs';\nexport default async (S, arg) => {\n  const [away, over] = arg.split('|');\n  const { page } = S.ctxs.inbox;\n  await page.setViewportSize({ width: 1440, height: 1500 });\n  await page.waitForTimeout(600);\n  const dialog = dialogOf(page);\n  const save = dialog.getByRole('button', { name: /^Book date/ }).first();\n  const footer = dialog.locator('div.shrink-0.border-t').last();\n  const style = () => save.evaluate((el) => { const c = getComputedStyle(el); return { disabled: el.disabled, background: c.backgroundColor, opacity: c.opacity, cursor: c.cursor }; });\n  await page.mouse.move(5, 5);\n  await page.waitForTimeout(400);\n  const rec = { at: new Date().toISOString(), away: await style() };\n  rec.awayPicture = await S.shot(page, away, { element: footer, settle: 200, shows: 'The held Book date with the mouse away' });\n  const b = await save.boundingBox();\n  await page.mouse.move(b.x + b.width / 2, b.y + b.height / 2);\n  await page.waitForTimeout(400);\n  rec.over = await style();\n  rec.overPicture = await S.shot(page, over, { element: footer, settle: 200, shows: 'The held Book date with the mouse over it' });\n  const cancel = dialog.getByRole('button', { name: 'Cancel', exact: true });\n  rec.cancelCursor = await cancel.evaluate((el) => getComputedStyle(el).cursor);\n  await page.mouse.move(5, 5);\n  (S.st.hover ??= []).push(rec);\n  S.save();\n  return rec;\n};\n",
 "steps/inbox-in.mjs": "// The staging administrator signed in through the launcher and handed into the inbox: one page for the thread\n// (the Book Date dialog stays open on it) and a second page of the same session for the Simulator dialog.\nexport default async (S) => {\n  if (!S.ctxs.inbox) {\n    const ctx = await S.newContext();\n    ctx.setDefaultTimeout(30000);\n    await S.launcherSignIn(ctx);\n    const page = await S.handTo(ctx, 'inbox');\n    const sim = await ctx.newPage();\n    S.ctxs.inbox = { ctx, page, sim };\n  }\n  const { ctx } = S.ctxs.inbox;\n  const me = await S.call(ctx, S.INBOX, 'GET', '/inbox/me');\n  S.assert.equal(me.status, 200, '/inbox/me ' + me.status);\n  const m = me.body;\n  S.addNames(m.name);\n  for (const p of m.people ?? []) S.addNames(p.name);\n  const birthdays = (m.teams ?? []).filter((t) => t.kind === 'birthdays').map((t) => ({ id: t.id, name: t.name, branchId: t.branchId, member: t.member }));\n  S.st.inboxViewer = {\n    accountId: m.accountId,\n    roles: m.roles,\n    capabilities: m.capabilities,\n    birthdaysTeams: birthdays,\n    simulatorAccounts: m.simulator?.channelAccounts ?? null,\n  };\n  S.save();\n  return { ...S.st.inboxViewer, namesHeld: S.NAMES.size };\n};\n",
 "steps/look.mjs": "// Picture preparation in the inbox: the Simulator side panel hidden, a tall viewport so the whole\n// workspace shows, and people's initials (avatar chips) masked as well as their names.\nexport const prepInbox = async (S, page) => {\n  await page.setViewportSize({ width: 1440, height: 1500 });\n  const hide = page.getByRole('button', { name: 'Hide', exact: true });\n  if (await hide.isVisible().catch(() => false)) {\n    await hide.click().catch(() => {});\n    await page.waitForTimeout(400);\n  }\n};\nexport const maskInitials = async (S, page) => {\n  const initials = new Set();\n  for (const n of S.NAMES) {\n    const words = n.split(/\\s+/).filter(Boolean);\n    if (words.length >= 2) initials.add((words[0][0] + words[1][0]).toUpperCase());\n    else if (words[0]?.length >= 2) initials.add(words[0].slice(0, 2).toUpperCase());\n  }\n  return page.evaluate((list) => {\n    const set = new Set(list);\n    let n = 0;\n    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);\n    const hits = [];\n    while (walker.nextNode()) {\n      const t = walker.currentNode;\n      if (set.has((t.nodeValue || '').trim())) hits.push(t);\n    }\n    for (const t of hits) {\n      const span = document.createElement('span');\n      span.setAttribute('data-redacted', '1');\n      span.style.cssText = 'background:#3f3f46;color:#3f3f46;border-radius:3px';\n      span.textContent = '██';\n      t.parentNode.replaceChild(span, t);\n      n += 1;\n    }\n    return n;\n  }, [...initials]);\n};\n/** The signed-in person's names from GET /api/me (employee name and nickname), held for masking (never written). */\nexport const namesIn = (S, body) => {\n  S.addNames(body?.employee?.name, body?.employee?.nickname);\n};\n",
 "steps/open.mjs": "// The ZZ TEST thread opened, its Book Date (or Create BEO) pressed, the model's reading of the chat waited for\n// (\"Read the whole chat\"), the window read (each box's value and placeholder, the choices, the footer's waiting line,\n// the save button's state and title) and pictured.\n// arg = \"<tag>|<key>|<picture file or ->|<book|beo>|<desk|phone>\".\nimport { dialogOf, readDialog, dialogShot, brief } from './bd.mjs';\nimport { prepInbox, maskInitials } from './look.mjs';\nimport { maskNumbers } from './thread.mjs';\nexport const VIEW = { desk: { width: 1440, height: 1500 }, phone: { width: 375, height: 812 } };\nexport default async (S, arg) => {\n  const [tag, key, pic = '-', which = 'book', vw = 'desk'] = arg.split('|');\n  const conv = S.st.convs[key];\n  if (!conv?.id) throw new Error('no conversation for ' + key);\n  if (!/^ZZ TEST/.test(conv.name)) throw new Error('refusing a conversation not named ZZ TEST');\n  const { page } = S.ctxs.inbox;\n  await page.setViewportSize(VIEW[vw]);\n  await page.goto(S.INBOX + '/?c=' + conv.id);\n  const chat = page.locator('section[aria-label=\"Conversation\"]');\n  await chat.waitFor({ timeout: 60000 });\n  const name = which === 'beo' ? 'Create BEO' : 'Book Date';\n  const button = chat.getByRole('button', { name, exact: true }).first();\n  await button.waitFor({ timeout: 60000 });\n  if (vw === 'desk') await prepInbox(S, page);\n  await page.waitForTimeout(1200);\n  const rec = { tag, at: new Date().toISOString(), key, conversationId: conv.id, pressed: name, viewport: VIEW[vw] };\n  rec.buttonsBefore = (await chat.getByRole('button', { name: /^(Book Date|Date Booked|Event archived|Create BEO)$/ }).allInnerTexts()).map((t) => t.trim());\n  const proposal = page.waitForResponse((r) => /\\/api\\/inbox\\/conversations\\/[^/]+\\/book-date-proposal$/.test(new URL(r.url()).pathname), { timeout: 120000 }).catch(() => null);\n  await button.click();\n  const dialog = dialogOf(page);\n  await dialog.locator('input[aria-label=\"Date\"]').waitFor({ timeout: 30000 });\n  const t0 = Date.now();\n  await dialog.getByTestId('book-date-read').waitFor({ timeout: 120000 }).catch(() => null);\n  rec.readWaitedMs = Date.now() - t0;\n  const p = await proposal;\n  rec.proposalRoute = { route: 'GET /api/inbox/conversations/:id/book-date-proposal', status: p ? p.status() : 'answered before the window opened' };\n  await page.waitForTimeout(700);\n  rec.dialog = await readDialog(S, page);\n  if (pic !== '-') {\n    if (vw === 'phone') {\n      await maskInitials(S, page);\n      await maskNumbers(page);\n      const phone = dialog.locator('input[aria-label=\"Phone\"]');\n      rec.picture = await S.shot(page, pic, { mask: [phone], settle: 400, shows: `${name} pressed at phone width (375 by 812): the window as it opens, after the chat is read` });\n    } else {\n      rec.picture = await dialogShot(S, page, pic, `${name} pressed on the ZZ TEST thread: the window as it read the chat, before anything is typed`);\n    }\n  }\n  (S.st.points ??= {})[tag] = rec;\n  S.save();\n  return { tag, key, pressed: name, readWaitedMs: rec.readWaitedMs, proposalRoute: rec.proposalRoute, buttonsBefore: rec.buttonsBefore, ...brief(rec.dialog), picture: rec.picture ?? null };\n};\n",
 "steps/phonepic.mjs": "// Point 8: the open window at phone width pictured with the phone box masked in the page itself (a solid fill that stays\n// under the footer, where a drawn mask would cover the footer), plus the footer alone; the footer measured: the waiting\n// line's width, height and lines, each button's width and whether its words wrap or are cut.\n// arg = \"<page picture>|<footer picture>|<what it shows>\".\nimport { dialogOf } from './bd.mjs';\nimport { maskInitials } from './look.mjs';\nimport { maskNumbers } from './thread.mjs';\nexport default async (S, arg) => {\n  const [pic, footPic, shows = ''] = arg.split('|');\n  const { page } = S.ctxs.inbox;\n  const dialog = dialogOf(page);\n  await dialog.locator('input[aria-label=\"Phone\"]').evaluate((el) => { el.style.color = '#3f3f46'; el.style.background = '#3f3f46'; el.style.webkitTextFillColor = '#3f3f46'; });\n  await maskInitials(S, page);\n  await maskNumbers(page);\n  const footer = dialog.locator('div.shrink-0.border-t').last();\n  const measure = await footer.evaluate((f) => {\n    const box = (el) => { const r = el.getBoundingClientRect(); return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) }; };\n    const line = f.querySelector('[data-testid=\"book-date-waiting\"]');\n    const lh = line ? parseFloat(getComputedStyle(line).lineHeight) || 16 : null;\n    const buttons = [...f.querySelectorAll('button')].map((b) => ({\n      text: b.innerText.replace(/\\s+/g, ' ').trim(), ...box(b), wrapsOrCut: b.scrollWidth > b.clientWidth + 1 || b.getBoundingClientRect().height > 40,\n      lines: Math.round(b.getBoundingClientRect().height / (parseFloat(getComputedStyle(b).lineHeight) || 20)),\n    }));\n    return {\n      footer: box(f), viewportWidth: window.innerWidth,\n      waitingLine: line ? { text: line.innerText.replace(/\\s+/g, ' ').trim(), ...box(line), lineHeight: lh, lines: Math.round(line.getBoundingClientRect().height / lh), charsPerLineAbout: Math.round(line.innerText.length / Math.max(1, Math.round(line.getBoundingClientRect().height / lh))) } : null,\n      buttons,\n    };\n  });\n  const rec = { at: new Date().toISOString(), measure };\n  rec.picture = await S.shot(page, pic, { settle: 400, shows: shows + ' (the whole screen at 375 by 812)' });\n  rec.footerPicture = await S.shot(page, footPic, { element: footer, settle: 200, shows: shows + ' (the footer alone)' });\n  (S.st.phone ??= []).push(rec);\n  S.save();\n  return rec;\n};\n",
 "steps/plan.mjs": "// SCRUM-955 staging proof: fresh ZZ TEST threads, each from its own new ZZ TEST simulator number, into the simulator\n// account \"Demo WhatsApp · Central Floresta\", the Category hint Birthdays & Events. Every name is invented.\n// A = the lane's steps 2-7 exactly (10 kids, then \"sorry, 12 kids, not 10\"): points 1, 2, 3, 8 and 7 (the booking).\n// B = the lane's step 8 (no count at all): point 4. C = the lane's step 9 (a stated zero): point 5.\n// D = the lane's step 10 exactly (the adults): point 6. E = the start time and the age read two ways: point 6.\n// T = A's two lines in Thai: the hunt (a Thai chip at phone width).\nexport const SIM_ACCOUNT = '01a156bb-6778-72b0-8237-6028f8874503'; // Demo WhatsApp · Central Floresta (simulator)\nexport const CONVS = {\n  A: { key: 'A', from: '66899955111', name: 'ZZ TEST 955 two ways', language: 'en', category: 'birthdays', text: 'Hi, a party on 12 December at 13:00 for 10 kids (ZZ TEST)' },\n  B: { key: 'B', from: '66899955112', name: 'ZZ TEST 955 no count', language: 'en', category: 'birthdays', text: 'Hi, a party on 12 December at 13:00 please (ZZ TEST)' },\n  C: { key: 'C', from: '66899955113', name: 'ZZ TEST 955 zero', language: 'en', category: 'birthdays', text: 'Party on 12 December at 13:00, 0 kids and 10 adults (ZZ TEST)' },\n  D: { key: 'D', from: '66899955114', name: 'ZZ TEST 955 adults', language: 'en', category: 'birthdays', text: 'Party on 12 December at 13:00 for 8 kids and 4 adults (ZZ TEST)' },\n  E: { key: 'E', from: '66899955115', name: 'ZZ TEST 955 time and age', language: 'en', category: 'birthdays', text: 'Party on 12 December at 13:00 for 8 kids, she turns 5 years (ZZ TEST)' },\n  T: { key: 'T', from: '66899955116', name: 'ZZ TEST 955 Thai two ways', language: 'th', category: 'birthdays', text: 'สวัสดีค่ะ จองงานวันเกิด วันที่ 12 ธันวาคม 13:00 เด็ก 10 คน (ZZ TEST)' },\n};\nexport const LINES = {\n  a2: 'sorry, 12 kids, not 10 (ZZ TEST)',\n  d2: 'sorry, 6 adults (ZZ TEST)',\n  e2: 'sorry, can we start at 15:00 instead? and she turns 6 years, not 5 (ZZ TEST)',\n  t2: 'ขอโทษค่ะ เด็ก 12 คน ไม่ใช่ 10 คน (ZZ TEST)',\n};\n",
 "steps/read.mjs": "// A ZZ TEST thread read through the inbox api as the signed-in team member: the conversation (status,\r\n// category, team, aiState), its openQuestions (slots, states, answers as the server read them; a name is never\r\n// stored), every message (the customer's ZZ TEST lines as sent; the assistant's lines kept with any long digit\r\n// run masked), and the assistant's pills with the turn's intents and reason. arg = \"<key>|<tag>\".\r\nconst scrub = (t) => (typeof t === 'string' ? t.replace(/\\+?\\d[\\d\\s().-]{5,}\\d/g, (m) => ((m.match(/\\d/g) || []).length >= 7 ? '[number]' : m)) : t);\r\nexport const readConv = async (S, key) => {\r\n  const conv = S.st.convs[key];\r\n  if (!conv?.id) throw new Error('thread ' + key + ' has no conversation yet');\r\n  const texts = new Set(conv.lines.map((l) => l.text));\r\n  const { ctx } = S.ctxs.inbox;\r\n  const d = await S.call(ctx, S.INBOX, 'GET', '/inbox/conversations/' + conv.id);\r\n  const c = d.body?.conversation ?? d.body;\r\n  const m = await S.call(ctx, S.INBOX, 'GET', '/inbox/conversations/' + conv.id + '/messages');\r\n  const raw = m.body?.messages ?? [];\r\n  const messages = raw.map((x) => ({\r\n    id: x.id, direction: x.direction, authorKind: x.authorKind, source: x.source ?? null, createdAt: x.createdAt, providerStatus: x.providerStatus ?? null,\r\n    body: x.authorKind === 'customer' ? (texts.has(x.body) ? x.body : x.body ? '(other text)' : null) : x.authorKind === 'staff' ? '(staff line)' : scrub(x.body ?? null),\r\n  }));\r\n  const events = (c?.events ?? []).map((e) => {\r\n    const p = e.payload ?? {};\r\n    const ai = String(e.kind).startsWith('ai_');\r\n    return {\r\n      kind: e.kind, createdAt: e.createdAt, actorKind: e.actorKind ?? null,\r\n      ...(ai ? {\r\n        turnId: p.turnId ?? null, intent: p.intent ?? null, intents: p.intents ?? null, reason: p.reason ?? null, rule: p.rule ?? null,\r\n        destination: p.destination ?? null, templateKey: p.templateKey ?? null, closingKey: p.closingKey ?? null, holdingLine: p.holdingLine ?? null,\r\n        silent: p.silent ?? null, messageIds: Array.isArray(p.messageIds) ? p.messageIds : null, rethink: p.rethink ?? null,\r\n        askBranch: p.askBranch ?? null, askedSlots: p.askedSlots ?? null, composition: p.composition ?? null, branchNamed: p.branchNamed ?? null,\r\n      } : {}),\r\n    };\r\n  });\r\n  const oq = (c?.openQuestions ?? []).map((q) => ({\r\n    id: q.id, slot: q.slot, state: q.state, answer: q.answer ?? null, askedMessageId: q.askedMessageId, answeredMessageId: q.answeredMessageId ?? null,\r\n    askedAt: q.askedAt, closedAt: q.closedAt ?? null,\r\n  }));\r\n  return {\r\n    at: new Date().toISOString(),\r\n    conversation: {\r\n      route: 'GET /api/inbox/conversations/:id', status: d.status,\r\n      state: c?.status ?? null, category: c?.category ?? null, teamName: c?.teamName ?? null, branchId: c?.branchId ?? null,\r\n      language: c?.language ?? null, aiMode: c?.aiMode ?? null, aiState: c?.aiState ?? null, aiPaused: c?.aiPaused ?? null, handledAt: c?.handledAt ?? null,\r\n      openQuestionsPresent: Array.isArray(c?.openQuestions),\r\n    },\r\n    openQuestions: oq,\r\n    messagesRoute: { route: 'GET /api/inbox/conversations/:id/messages', status: m.status },\r\n    messages,\r\n    aiPills: events.filter((e) => String(e.kind).startsWith('ai_')),\r\n    otherPills: (c?.events ?? []).filter((e) => !String(e.kind).startsWith('ai_')).map((e) => ({ kind: e.kind, actorKind: e.actorKind ?? null, createdAt: e.createdAt, ...(e.kind === 'branch_set' ? { branchId: e.payload?.branchId ?? null, byAi: e.payload?.byAi ?? null, payloadKeys: Object.keys(e.payload ?? {}) } : {}) })),\r\n  };\r\n};\r\nexport default async (S, arg) => {\r\n  const [key, tag = 'read'] = arg.split('|');\r\n  const r = await readConv(S, key);\r\n  (S.st.convs[key].reads ??= {})[tag] = r;\r\n  S.save();\r\n  return r;\r\n};\r\n",
 "steps/send.mjs": "// One ZZ TEST customer line sent through the inbox's own Settings › Simulator · test only dialog into\n// Demo WhatsApp · Central Floresta from the thread's own ZZ TEST number, the Category hint Birthdays & Events\n// and the thread's language — on the session's SECOND page, so the thread page (and a dialog open on it) is\n// untouched. The dialog's own POST /api/inbox/simulator/inbound is read.\n// arg = \"<key>\" (the thread's opener) or \"<key>|<text>\" (a later line of the same thread).\nimport { CONVS, SIM_ACCOUNT, LINES } from './plan.mjs';\nexport default async (S, arg) => {\n  const [key, ...rest] = arg.split('|');\n  const C = CONVS[key];\n  if (!C) throw new Error('no thread ' + key);\n  // \"@a2\" names a line of plan.LINES.\n  const text = rest.length ? (rest[0].startsWith('@') ? LINES[rest[0].slice(1)] : rest.join('|')) : C.text;\n  if (!text) throw new Error('no text for ' + arg);\n  const conv = (S.st.convs[C.key] ??= { from: 'a ZZ TEST simulator number', name: C.name, language: C.language, category: C.category, expect: C.expect, lines: [] });\n  if (!rest.length && conv.lines[0]?.status === 200) return { already: conv.lines[0] };\n  const page = S.ctxs.inbox.sim;\n  await page.setViewportSize({ width: 1440, height: 900 });\n  await page.goto(S.INBOX + '/');\n  const settings = page.getByRole('button', { name: 'Settings', exact: true });\n  await settings.waitFor({ timeout: 60000 });\n  await settings.click();\n  await page.getByRole('menuitem', { name: 'Simulator · test only' }).click();\n  const dlg = page.getByRole('dialog').filter({ hasText: 'Pretend customers, through the real webhook' });\n  await dlg.waitFor({ timeout: 30000 });\n  const send = dlg.getByRole('button', { name: 'Send as the customer' });\n  const form = dlg.locator('form').filter({ has: page.getByRole('button', { name: 'Send as the customer' }) });\n  await form.locator('select').nth(0).selectOption(SIM_ACCOUNT);\n  const inputs = form.locator('input:not([type=file])');\n  await inputs.nth(0).fill(C.from);\n  await inputs.nth(1).fill(C.name);\n  await form.locator('select').nth(1).selectOption(C.category);\n  await form.locator('select').nth(2).selectOption(C.language);\n  await form.locator('textarea').fill(text);\n  const formState = {\n    account: await form.locator('select').nth(0).evaluate((e) => e.options[e.selectedIndex]?.text ?? null),\n    category: await form.locator('select').nth(1).evaluate((e) => e.options[e.selectedIndex]?.text ?? null),\n    language: await form.locator('select').nth(2).inputValue(),\n    message: await form.locator('textarea').inputValue(),\n  };\n  const [resp] = await Promise.all([\n    page.waitForResponse((r) => new URL(r.url()).pathname === '/api/inbox/simulator/inbound' && r.request().method() === 'POST', { timeout: 90000 }),\n    send.click(),\n  ]);\n  let body = null;\n  try { body = await resp.json(); } catch {}\n  let sent = null;\n  try {\n    const j = resp.request().postDataJSON();\n    sent = { channelAccountId: j.channelAccountId, text: j.text ?? null, hint: j.hint ?? null };\n  } catch {}\n  const rec = {\n    n: conv.lines.length + 1, by: 'customer', text, at: new Date().toISOString(),\n    path: 'the inbox UI: Settings › Simulator · test only › A customer writes › Send as the customer (its own POST /api/inbox/simulator/inbound)',\n    formState, requestSent: sent, status: resp.status(),\n    outcome: body?.outcome ?? null, conversationsCreated: body?.conversationsCreated ?? null, reopened: body?.reopened ?? null,\n    conversationIds: body?.conversationIds ?? null, error: resp.status() === 200 ? null : body?.error ?? body,\n  };\n  conv.lines.push(rec);\n  if (resp.status() === 200 && rec.conversationIds?.[0]) {\n    if (conv.id && conv.id !== rec.conversationIds[0]) rec.note = 'a different conversation id than the thread had';\n    conv.id ??= rec.conversationIds[0];\n  }\n  S.save();\n  await page.waitForTimeout(800);\n  rec.dialogSaid = await dlg.getByText(/^Received/).first().innerText({ timeout: 3000 }).catch(() => null);\n  await page.keyboard.press('Escape').catch(() => {});\n  S.save();\n  if (resp.status() !== 200) throw new Error('simulator refused ' + resp.status() + ' ' + JSON.stringify(rec.error).slice(0, 300));\n  return rec;\n};\n",
 "steps/signout.mjs": "// Every session signed out, each read back: the inbox context (the inbox, the BEO tab's OTO App session, the\n// launcher) and the app context (the OTO App, the launcher).\nexport default async (S) => {\n  const safe = (p) => p.catch((e) => ({ status: 'error ' + e.message }));\n  const out = {};\n  if (S.ctxs.inbox) {\n    const { ctx } = S.ctxs.inbox;\n    const a = await safe(S.call(ctx, S.INBOX, 'POST', '/auth/sign-out', {}));\n    const app = await safe(S.call(ctx, S.APP, 'POST', '/logout', {}));\n    const b = await safe(S.call(ctx, S.LAUNCHER, 'POST', '/auth/sign-out', {}));\n    out.inboxContext = {\n      inboxSignOut: { route: 'POST /api/auth/sign-out (inbox)', status: a.status },\n      beoTabAppLogout: { route: 'POST /api/logout (OTO App, the BEO tab)', status: app.status },\n      launcherSignOut: { route: 'POST /api/auth/sign-out (launcher)', status: b.status },\n      readBack: {\n        inboxMe: (await safe(S.call(ctx, S.INBOX, 'GET', '/inbox/me'))).status,\n        appUser: (await safe(S.call(ctx, S.APP, 'GET', '/user'))).status,\n        launcherMe: (await safe(S.call(ctx, S.LAUNCHER, 'GET', '/me'))).status,\n      },\n    };\n  }\n  if (S.ctxs.app) {\n    const { ctx } = S.ctxs.app;\n    const a = await safe(S.call(ctx, S.APP, 'POST', '/logout', {}));\n    const b = await safe(S.call(ctx, S.LAUNCHER, 'POST', '/auth/sign-out', {}));\n    out.appContext = {\n      appLogout: { route: 'POST /api/logout (OTO App)', status: a.status },\n      launcherSignOut: { route: 'POST /api/auth/sign-out (launcher)', status: b.status },\n      readBack: {\n        appUser: (await safe(S.call(ctx, S.APP, 'GET', '/user'))).status,\n        launcherMe: (await safe(S.call(ctx, S.LAUNCHER, 'GET', '/me'))).status,\n      },\n    };\n  }\n  if (S.ctxs.pos) {\n    const { api } = S.ctxs.pos;\n    const a = await api.post('/api/auth/sign-out', { data: {}, headers: { 'Idempotency-Key': S.randomUUID() } }).then((r) => r.status()).catch((e) => 'error ' + e.message);\n    const me = await api.get('/api/me').then((r) => r.status()).catch((e) => 'error ' + e.message);\n    out.tillOrigin = { signOut: { route: 'POST /api/auth/sign-out (till origin)', status: a }, readBack: { me } };\n    await api.dispose().catch(() => {});\n  }\n  S.st.signOut = { at: new Date().toISOString(), ...out };\n  (S.st.signOuts ??= []).push(S.st.signOut);\n  S.save();\n  return S.st.signOut;\n};\n",
 "steps/thread.mjs": "// Masks every phone-like run of nine or more digits in the visible text (the ZZ TEST simulator numbers included).\nexport const maskNumbers = (page) => page.evaluate(() => {\n  const re = /\\+?\\d[\\d\\s().-]{6,}\\d/g;\n  let n = 0;\n  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);\n  const hits = [];\n  while (walker.nextNode()) {\n    const t = walker.currentNode;\n    re.lastIndex = 0;\n    const v = t.nodeValue || '';\n    const runs = v.match(re) || [];\n    if (runs.some((m) => (m.match(/\\d/g) || []).length >= 9 && !(m.match(/\\d/g) || []).join('').endsWith('898700417')) && !t.parentElement?.closest('[data-redacted]')) hits.push(t);\n  }\n  for (const t of hits) {\n    let html = (t.nodeValue || '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));\n    html = html.replace(re, (m) => {\n      if ((m.match(/\\d/g) || []).length < 9) return m;\n      // SCRUM-904: the husband's number in thread A is invented for this proof (089 870 0417): left readable.\n      if ((m.match(/\\d/g) || []).join('').endsWith('898700417')) return m;\n      n += 1;\n      return `<span data-redacted=\"1\" style=\"background:#3f3f46;color:#3f3f46;border-radius:3px\">${m.replace(/./g, '█')}</span>`;\n    });\n    const span = document.createElement('span');\n    span.setAttribute('data-redacted', 'wrap');\n    span.innerHTML = html;\n    t.parentNode.replaceChild(span, t);\n  }\n  return n;\n});\n",
 "steps/wait.mjs": "// After a customer line: the thread read every 5 s until the assistant's turn for it shows (a new ai_ pill:\n// replied, handed over, left silent…) or the limit passes. Records the turn's intents and reason, the assistant's\n// new lines, the thread's openQuestions and aiState. arg = \"<key>|<limit s>\".\nimport { readConv } from './read.mjs';\nexport default async (S, arg) => {\n  const [key, limitS = '120'] = arg.split('|');\n  const conv = S.st.convs[key];\n  const n = conv.lines.length;\n  const seen = new Set(conv.seenTurns ?? []);\n  const t0 = Date.now();\n  let r;\n  let fresh = [];\n  for (;;) {\n    r = await readConv(S, key);\n    fresh = r.aiPills.filter((p) => p.turnId && !seen.has(p.turnId));\n    if (fresh.length > 0 || Date.now() - t0 > Number(limitS) * 1000) break;\n    await new Promise((res) => setTimeout(res, 5000));\n  }\n  // A moment more, so a turn's second pill (a reply then a hand-over) and its lines are in.\n  if (fresh.length > 0) {\n    await new Promise((res) => setTimeout(res, 4000));\n    r = await readConv(S, key);\n    fresh = r.aiPills.filter((p) => p.turnId && !seen.has(p.turnId));\n  }\n  const lastCustomer = [...r.messages].reverse().find((m) => m.authorKind === 'customer');\n  const idx = r.messages.indexOf(lastCustomer);\n  const ids = new Set(fresh.flatMap((p) => p.messageIds ?? []));\n  const newLines = r.messages.filter((m, i) => m.authorKind === 'ai' && (ids.has(m.id) || i > idx));\n  const out = {\n    afterLine: n, waitedMs: Date.now() - t0, turnShown: fresh.length > 0,\n    turns: fresh.map((p) => ({ kind: p.kind, turnId: p.turnId, intent: p.intent, intents: p.intents, reason: p.reason, rule: p.rule, closingKey: p.closingKey, rethink: p.rethink })),\n    assistantLines: newLines.map((m) => ({ id: m.id, createdAt: m.createdAt, providerStatus: m.providerStatus, body: m.body })),\n    aiState: r.conversation.aiState,\n    openQuestions: r.openQuestions,\n  };\n  conv.seenTurns = [...seen, ...fresh.map((p) => p.turnId)];\n  (conv.turns ??= {})[n] = out;\n  (conv.reads ??= {})['after' + n] = r;\n  S.save();\n  return out;\n};\n",
 "bundle.cjs": "// Writes docs/qa/proof-2026-11-13/SCRUM-955/proof.mjs: every script of the run as text; `node proof.mjs <folder>` writes them out.\nconst fs = require('fs');\nconst path = require('path');\nconst H = process.argv[2];\nconst OUT = process.argv[3];\nconst files = ['driver.mjs', 'go.mjs', 'deploys.mjs', 'receipt.mjs', ...fs.readdirSync(path.join(H, 'steps')).filter((f) => f.endsWith('.mjs')).sort().map((f) => 'steps/' + f)];\nconst map = Object.fromEntries(files.map((f) => [f, fs.readFileSync(path.join(H, f), 'utf8')]));\nmap['bundle.cjs'] = fs.readFileSync(path.join(H, '..', 'bundle.cjs'), 'utf8');\nconst head = `// SCRUM-955 staging proof harness (Book Date: an empty count shows the dash, not 0; a count or another figure the chat\n// reads two ways holds Book date until a reading is picked or a figure typed), as run on 13 November 2026 (Bangkok) against\n// oto-inbox-staging dep-dbr03856e07s738ne6d0 at b70798d3e (the landed lane, the inbox only). Built on the SCRUM-947 harness\n// (sign-in, the Simulator, the dialog reader) and the SCRUM-944 booking and archive steps. One file: every script of the run as\n// text; \\`node proof.mjs <folder>\\` writes them out. The driver keeps ONE headless Chromium open and runs a step per request\n// (node go.mjs <step> \"<arg>\"); credentials by NAME only through scripts/agent/env.mjs need(); staff names held in memory for\n// masking only; ZZ TEST names and new ZZ TEST simulator numbers.\n// The run, in order: deploys.mjs atStart | inbox-in | app-in 2026-12-12 (the day check) | send A,B,C,D,E,T | wait A,D,E,T|90 |\n// send A|@a2 D|@d2 E|@e2 T|@t2 | wait A,D,E,T|60, B,C|30 | open p1|A|01 | act p1.press press-save (02) | act p1.type11 type:Kids 11\n// (03) | act p1.del11 back:Kids 2 (04) | act p1.space type:Kids ␠ (05) | act p1.delspace back:Kids 1 | act p1.pick10 pick:kids 10\n// (06) | act p1.cancel (07) | open p4|B|08 | act p4.adults0 type:Adults 0 (09) | act p4.cancel | open p5|C|10 | act p5.cancel |\n// open p6d|D|11 | act p6d.cancel | open p6e|E|12 | act p6e.pick15 pick:startTime 15:00 (13) | act p6e.age6 type:Turning age 6 (14)\n// | act p6e.cancel | open p8b|A|-|book|phone | phonepic 15,16 | act p8b.cancel | open p8c|A|-|beo|phone | phonepic 17,18 | act\n// p8c.cancel | open p9t|T|-|book|phone | phonepic 19,20 | hover 21,22 | act p9t.cancel | app-in 2026-12-12 (the day again) | open\n// p7|A | act p7.pick12 pick:kids 12 (23) | book A|24 | cleanup (the event archived, every conversation handled, read back) |\n// chatpic A|25 | GET /STOP (signs every session out, closes the browser) | deploys.mjs after | receipt.mjs | bundle.cjs.\nimport { mkdirSync, writeFileSync } from 'node:fs';\nimport { dirname, resolve } from 'node:path';\nconst FILES = {\n`;\nconst body = Object.entries(map).map(([k, v]) => ' ' + JSON.stringify(k) + ': ' + JSON.stringify(v)).join(',\\n');\nconst tail = `\n};\nconst out = resolve(process.argv[2] ?? '.');\nfor (const [n, t] of Object.entries(FILES)) { const p = resolve(out, n); mkdirSync(dirname(p), { recursive: true }); writeFileSync(p, t); }\nconsole.log('written ' + Object.keys(FILES).length + ' files to ' + out);\n`;\nfs.writeFileSync(OUT, head + body + tail);\nconsole.log('bundled', Object.keys(map).length, 'files');\n"
};
const out = resolve(process.argv[2] ?? '.');
for (const [n, t] of Object.entries(FILES)) { const p = resolve(out, n); mkdirSync(dirname(p), { recursive: true }); writeFileSync(p, t); }
console.log('written ' + Object.keys(FILES).length + ' files to ' + out);
